</style></head><body><h1>Vaccine Demand Forecast and Inventory Planning</h1><div class="meta"><strong>Location:</strong> {{ $location }} &nbsp; <strong>Forecast:</strong> {{ $months }} months &nbsp; <strong>Schedule basis:</strong> {{ $version?->name ?? 'Latest active schedule' }}<br><span class="muted">Generated {{ now()->format('M d, Y h:i A') }}</span></div><div class="note">Planning advisory only. Estimated demand combines scheduled doses, catch-up backlog, and historical vaccination activity. A negative projected balance indicates a possible shortage for staff review.</div><table><thead><tr><th>Vaccine</th><th class="number">Scheduled due</th><th class="number">Catch-up backlog</th><th class="number">Recent 3 months</th><th class="number">Estimated demand</th><th class="number">Available stock</th><th class="number">Projected balance</th><th>Status</th></tr></thead><tbody>@forelse($demand as $row)<tr><td><strong>{{ $row['vaccine']->name }}</strong></td><td class="number">{{ $row['scheduled_due'] }}</td><td class="number">{{ $row['catch_up_backlog'] }}</td><td class="number">{{ $row['recent_three_months'] }}</td><td class="number"><strong>{{ $row['estimated_demand'] }}</strong></td><td class="number">{{ $row['available_stock'] }}</td><td class="number {{ $row['projected_balance'] < 0 ? 'shortage' : 'sufficient' }}">{{ $row['projected_balance'] >= 0 ? '+' : '' }}{{ $row['projected_balance'] }}</td><td class="{{ $row['stock_status'] }}">{{ ucfirst($row['stock_status']) }}</td></tr>@empty<tr><td colspan="8" class="muted">No demand data available.</td></tr>@endforelse</tbody></table></body></html>
